#include <stdio.h>
#include <time.h>

// Include the trusted helloworld header that is generated
// during the build. This file is generated by calling the
// sdk tool oeedger8r against the helloworld.edl file.
#include "helloworld_t.h"

// This is the function that the host calls. It prints
// a message in the enclave before calling back out to
// the host to print a message from there too.
void enclave_helloworld()
{
    // Purposely use up all memory in the enclave
    int size = 1024;
    int multiplier = 1;
    while (multiplier++ < 4090) {
        int myArray[size * multiplier];
        myArray[size * multiplier - 1] = multiplier;
        int myArraySize = (int) sizeof(myArray);
        if (myArraySize == 10485760) {
            fprintf(stdout, "Now exceeding 10Mi for array size: Reclamation should have began by now assuuming 10Mi limit.\n");
        }
        // Print a message from the enclave. Note that this
        // does not directly call fprintf, but calls into the
        // host and calls fprintf from there. This is because
        // the fprintf function is not part of the enclave
        // as it requires support from the kernel.
        fprintf(stdout, "Hello world from the enclave. Size of array is %d\n", myArraySize);
        // sleep for 25 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 25000000;
        nanosleep(&ts, NULL);
    }
    sleep(60);

    // Call back into the host
    oe_result_t result = host_helloworld();
    if (result != OE_OK)
    {
        fprintf(
            stderr,
            "Call to host_helloworld failed: result=%u (%s)\n",
            result,
            oe_result_str(result));
    }
}
